using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver so metadata is populated for known types.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1️⃣  Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// 2️⃣  Probe without throwing: TryGetTypeInfo returns false if unavailable.
//     Use options *without* a resolver to simulate "not available".
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null   // no resolver → nothing can be resolved
};

bool found = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo(Person) on empty options → found={found}, info={info?.Type.Name ?? "(null)"}");

// Also show the success path for TryGetTypeInfo:
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(Person) on full options  → found={found2}, info={info2?.Type.Name ?? "(null)"}");

// If you need the strongly-typed version from TryGetTypeInfo, just cast:
if (found2 && info2 is JsonTypeInfo<Person> typed)
{
    Console.WriteLine($"  Cast succeeded → JsonTypeInfo<{typed.Type.Name}>");
}

public record Person(string Name, int Age);

